"""Meal Plan page: 7-day plan generated by the Meal Planner Agent."""
import pandas as pd
import streamlit as st

from core.orchestrator import run_workflow
from core.report import MEAL_ORDER, day_totals_df, meal_plan_to_df
from core.state import STAGES, get_profile, init_state
from ui.components import disclaimer, empty_state, explain_card, metric_card, page_header
from ui.components import STRETCH, lazy_tabs
from ui.theme import COLORS, apply_theme

init_state()
apply_theme()
page_header("7-Day Meal Plan", "Built from your Indian food database and meal templates - deterministic, no LLM.", "🍽️")

profile = get_profile()
if not profile:
    empty_state("No profile yet", "Save your profile first so the Planner knows your goal and constraints.",
                "ui/pages/2_Profile.py", "Open Profile & Goals")
    st.stop()

plan = st.session_state["meal_plan"]
left, right = st.columns([3, 1])
left.caption(f"{profile['goal']} · {profile['diet']} · {profile['cuisine']} · ₹{profile['budget_weekly_inr']:,}/week · "
             f"≤{profile['max_prep_time_min']} min per dish · allergies: {', '.join(profile['allergies']) or 'none'}")
label = "🔄 Regenerate plan" if plan else "▶ Generate 7-day plan"
if right.button(label, type="primary", **STRETCH):
    variation = (plan["variation"] + 1) if plan else 0
    with st.spinner("Planner → Nutrition → Meal Planner..."):
        ok = run_workflow(profile, variation)
    if ok:
        st.rerun()
    st.error("The meal plan could not be generated. Check the Agent Log for details.")

if plan is None:
    st.info("Press **Generate 7-day plan**. The Planner and Nutrition agents run first if needed.")
    st.write("")
    disclaimer()
    st.stop()

t, w = st.session_state["targets"], plan["weekly"]
stages = st.session_state["workflow_stages"]
icons = {"pending": "⚪", "running": "🟡", "done": "🟢", "warning": "🟠", "failed": "🔴"}
st.caption("Workflow: " + "  →  ".join(f"{icons[stages[s]]} {s}" for s in STAGES))

c = st.columns(4)
with c[0]: metric_card("Avg calories / day", f"{w['avg_calories']:,} kcal", f"Target {t['calories']:,} kcal")
with c[1]: metric_card("Avg protein / day", f"{w['avg_protein_g']} g", f"Target {t['protein_g']} g")
with c[2]: metric_card("Weekly grocery cost", f"₹{w['cost_inr']:,.0f}", f"Budget ₹{w['budget_inr']:,}")
with c[3]: metric_card("Generated in", f"{plan['generation_ms']} ms", f"Variation #{plan['variation']} · {plan['templates_considered']} templates")
st.write("")
st.progress(min(w["cost_inr"] / w["budget_inr"], 1.0), text=f"Budget used: {w['cost_inr'] / w['budget_inr']:.0%}")

val = st.session_state["validation"]
if val:
    v1, v2 = st.columns([4, 1])
    icon = {"passed": "✅", "passed_with_warnings": "⚠️", "revision_required": "❌"}[val["report"]["overall_status"]]
    v1.markdown(f"{icon} **{val['report']['overall_label']}** · score {val['report']['score']}/100 · "
                f"{val['revisions_used']} revision(s) by the Meal Planner after Validator feedback")
    v2.page_link("ui/pages/5_Validation.py", label="Details", icon="🔎")
else:
    st.caption("Validation status: **not yet validated** - open the Validation page to run it.")
if plan["warnings"]:
    with st.expander(f"⚠️ {len(plan['warnings'])} remaining planner note(s)", expanded=False):
        for x in plan["warnings"]:
            st.markdown(f"- {x}")

view = lazy_tabs(["📅 Day view", "🗓️ Full week", "📈 Weekly charts", "🧠 Why this plan"], "mp_view")

if view.startswith("📅"):
    day_no = st.radio("Day", [d["day"] for d in plan["days"]], horizontal=True, format_func=lambda n: f"Day {n}")
    day = plan["days"][day_no - 1]
    st.markdown(f"**{day['template_name']}**")
    explain_card(day["rationale"])
    if day.get("adaptation_notes"):
        st.info("**Adapted from your feedback:**\n" + "\n".join(f"- {n}" for n in day["adaptation_notes"]))
    if day.get("revision_notes"):
        st.info("**Revised after Validator feedback:**\n" + "\n".join(f"- {n}" for n in day["revision_notes"]))
    st.write("")
    for slot in MEAL_ORDER:
        meal = day["meals"][slot]
        title = "Evening snack" if slot == "Snack" else slot
        with st.container(border=True):
            h1, h2 = st.columns([3, 2])
            tag = " · ⏭️ skipped (reported by you)" if meal.get("skipped") else (" · 🍴 ate out (estimated)" if meal.get("ate_out") else "")
            h1.markdown(f"**{title}**{tag}")
            mt = meal["totals"]
            h2.caption(f"{mt['calories']:.0f} kcal · {mt['protein_g']:.0f} g protein · ₹{mt['cost_inr']:.0f}")
            if not meal["items"]:
                st.caption("No food logged for this meal.")
                continue
            st.dataframe(pd.DataFrame([{
                "Food": i["food_name"], "Portion": f"{i['servings']:g} × {i['serving_label']}", "Grams": i["grams"],
                "kcal": i["calories"], "Protein": i["protein_g"], "Carbs": i["carbs_g"], "Fat": i["fat_g"],
                "Fiber": i["fiber_g"], "Cost ₹": i["cost_inr"]} for i in meal["items"]]),
                hide_index=True, **STRETCH)
    st.markdown("**Daily totals vs targets**")
    dt = day["totals"]
    for name, got, goal, unit in [("Calories", dt["calories"], t["calories"], "kcal"), ("Protein", dt["protein_g"], t["protein_g"], "g"),
                                  ("Carbs", dt["carbs_g"], t["carbs_g"], "g"), ("Fat", dt["fat_g"], t["fat_g"], "g"),
                                  ("Fiber", dt["fiber_g"], t["fiber_g"], "g")]:
        st.progress(min(got / goal, 1.0), text=f"{name}: {got:.0f} / {goal} {unit} ({got / goal:.0%})")
    st.caption(f"Estimated cost for the day: ₹{dt['cost_inr']:.0f}")

if view.startswith("🗓️"):
    totals = day_totals_df(plan)
    st.markdown("**Daily totals**")
    st.dataframe(totals, hide_index=True, **STRETCH)
    st.markdown("**Every meal item**")
    full = meal_plan_to_df(plan)
    st.dataframe(full, hide_index=True, **STRETCH, height=420)
    st.download_button("⬇️ Download meal plan (CSV)", full.to_csv(index=False), file_name="nutriplan_meal_plan.csv", mime="text/csv")

if view.startswith("📈"):
    totals = day_totals_df(plan).set_index("Day")
    a, b = st.columns(2)
    with a:
        st.markdown("**Calories per day vs target**")
        st.line_chart(pd.DataFrame({"Calories": totals["Calories"], "Target": t["calories"]}), color=[COLORS["green"], COLORS["muted"]])
        st.markdown("**Cost per day vs daily budget (₹)**")
        st.bar_chart(pd.DataFrame({"Cost": totals["Cost (₹)"]}), color=COLORS["teal"])
    with b:
        st.markdown("**Protein per day vs target (g)**")
        st.line_chart(pd.DataFrame({"Protein": totals["Protein (g)"], "Target": t["protein_g"]}), color=[COLORS["green"], COLORS["muted"]])
        st.markdown("**Fiber per day (g)**")
        st.bar_chart(pd.DataFrame({"Fiber": totals["Fiber (g)"]}), color=COLORS["teal"])

if view.startswith("🧠"):
    st.markdown("**How each day was chosen**")
    for d in plan["days"]:
        st.markdown(f"- **Day {d['day']}:** {d['rationale']}")
    st.markdown("**Substitutions made to respect your constraints**")
    if plan["substitutions"]:
        st.dataframe(pd.DataFrame(plan["substitutions"]).rename(columns=str.title), hide_index=True, **STRETCH)
    else:
        st.write("None needed - every template item already fit your diet, allergies, cuisine and cooking-time limits.")
    st.markdown("**Main-dish repeats this week** (rule: no main dish more than twice)")
    counts = pd.Series(plan["main_dish_counts"]).sort_values(ascending=False)
    st.dataframe(counts.rename("Times used").to_frame(), **STRETCH)

st.write("")
disclaimer()
